//! The fixture schema (`mcp-re-delegation-conformance/v1`), the manifest that pins the
//! corpus, the wire conversions, and where the committed corpus lives.

use std::path::Path;
use std::path::PathBuf;

use serde::Deserialize;
use serde::Serialize;

use mcp_re_http_profile::HttpRequest;
use mcp_re_http_profile::HttpResponse;

use super::material::AUD_SCOPE;
use super::material::EPOCH;
use super::material::VERIFIER_AUD;

pub(super) const SCHEMA: &str = "mcp-re-delegation-conformance/v1";

/// Third-party KATs committed here but NOT generated by the writer: pinned by
/// hash, replayed by their own harness (`delegation_cross_verification_test`).
pub(super) const EXTERNAL_KATS: [&str; 1] = ["external_delegation_kat.json"];

#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub(super) struct WireMessage {
    method: Option<String>,
    target_uri: Option<String>,
    status: Option<u16>,
    headers: Vec<(String, String)>,
    body_utf8: String,
}

/// The verifier-side deployment policy a fixture pins (ADR-MCPRE-052 §3). The
/// same frozen response can be accepted or rejected depending on this policy
/// (e.g. a valid credential is `audience_mismatch` at a verifier not named in
/// `aud`, or `trust_epoch_stale` once the accepted-epoch set advances).
#[derive(Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub(super) struct DelegationCheck {
    pub(super) verifier_audiences: Vec<String>,
    pub(super) expected_audience_hash: String,
    pub(super) accepted_epochs: Vec<String>,
    pub(super) max_clock_skew: i64,
    pub(super) revoked_kids: Vec<String>,
}

impl DelegationCheck {
    /// The nominal in-policy verifier: this audience, this scope, the current
    /// epoch, nothing revoked.
    pub(super) fn nominal() -> Self {
        DelegationCheck {
            verifier_audiences: vec![VERIFIER_AUD.into()],
            expected_audience_hash: AUD_SCOPE.into(),
            accepted_epochs: vec![EPOCH.into()],
            max_clock_skew: 60,
            revoked_kids: vec![],
        }
    }
}

#[derive(Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub(super) struct Fixture {
    schema: String,
    pub(super) name: String,
    /// Always `delegated_response`: verify `response` against `request` through
    /// `verify_delegated_response_full` with the fixture `check` policy.
    pub(super) kind: String,
    /// `verify_ok` or the exact frozen `mcp-re.*` wire code observed.
    pub(super) expected: String,
    request: WireMessage,
    response: WireMessage,
    pub(super) check: DelegationCheck,
}

/// A fixture's name and the verdict it freezes.
#[derive(Clone, Copy)]
pub(super) struct Verdict<'a> {
    pub(super) name: &'a str,
    pub(super) expected: &'a str,
}

impl Fixture {
    pub(super) fn new(
        verdict: Verdict,
        request: WireMessage,
        response: &HttpResponse,
        check: DelegationCheck,
    ) -> Self {
        Fixture {
            schema: SCHEMA.into(),
            name: verdict.name.into(),
            kind: "delegated_response".into(),
            expected: verdict.expected.into(),
            request,
            response: wire_response(response),
            check,
        }
    }

    pub(super) fn request(&self) -> HttpRequest {
        from_wire_request(&self.request)
    }

    pub(super) fn response(&self) -> HttpResponse {
        from_wire_response(&self.response)
    }
}

#[derive(Debug, Serialize, Deserialize)]
pub(super) struct Manifest {
    pub(super) schema: String,
    pub(super) verify_at_unix: i64,
    /// SHA-256 over the sorted `path:hash` list (#415 rev 2 §12.2) — one value
    /// naming this exact corpus, since a tag or a filename list proves only which
    /// files were MEANT to be there, not what was in them.
    pub(super) corpus_digest: String,
    pub(super) fixtures: Vec<ManifestEntry>,
}

/// One manifest entry: the fixture path and the SHA-256 of its exact bytes.
#[derive(Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub(super) struct ManifestEntry {
    pub(super) file: String,
    pub(super) sha256: String,
}

pub(super) fn hex_sha256(bytes: &[u8]) -> String {
    use sha2::Digest;
    sha2::Sha256::digest(bytes)
        .iter()
        .map(|b| format!("{b:02x}"))
        .collect()
}

/// The §12.2 corpus digest over the SORTED `<path>:<sha256>` list — sorted so the
/// digest tracks corpus CONTENT, not the writer's emission order.
pub(super) fn corpus_digest(entries: &[ManifestEntry]) -> String {
    let mut lines: Vec<String> = entries
        .iter()
        .map(|e| format!("{}:{}\n", e.file, e.sha256))
        .collect();
    lines.sort();
    hex_sha256(lines.concat().as_bytes())
}

pub(super) fn wire_request(r: &HttpRequest) -> WireMessage {
    WireMessage {
        method: Some(r.method.clone()),
        target_uri: Some(r.target_uri.clone()),
        status: None,
        headers: r.headers.clone(),
        body_utf8: String::from_utf8(r.body.clone()).expect("utf-8 body"),
    }
}

fn wire_response(r: &HttpResponse) -> WireMessage {
    WireMessage {
        method: None,
        target_uri: None,
        status: Some(r.status),
        headers: r.headers.clone(),
        body_utf8: String::from_utf8(r.body.clone()).expect("utf-8 body"),
    }
}

fn from_wire_request(w: &WireMessage) -> HttpRequest {
    HttpRequest {
        method: w.method.clone().expect("request method"),
        target_uri: w.target_uri.clone().expect("request target_uri"),
        headers: w.headers.clone(),
        body: w.body_utf8.clone().into_bytes(),
    }
}

fn from_wire_response(w: &WireMessage) -> HttpResponse {
    HttpResponse {
        status: w.status.expect("response status"),
        headers: w.headers.clone(),
        body: w.body_utf8.clone().into_bytes(),
    }
}

/// The manifest's directory inside the Bazel runfiles, or relative to the cwd.
fn runfile_manifest_dir(rel: &str) -> Option<PathBuf> {
    let under_runfiles = ["TEST_SRCDIR", "RUNFILES_DIR"]
        .iter()
        .filter_map(|key| std::env::var(key).ok())
        .map(|root| Path::new(&root).join(rel));
    under_runfiles
        .chain(std::iter::once(PathBuf::from(rel)))
        .find(|candidate| candidate.exists())
        .map(|candidate| candidate.parent().expect("manifest parent").to_path_buf())
}

/// Locate the committed corpus under BOTH build systems (same dual-mode bridge
/// as the http-profile corpus).
pub(super) fn vectors_root() -> PathBuf {
    match std::env::var("MCP_RE_DELEGATION_VECTORS_MANIFEST") {
        Ok(rel) => runfile_manifest_dir(&rel).unwrap_or_else(|| {
            panic!("MCP_RE_DELEGATION_VECTORS_MANIFEST set but runfile not found (rel={rel})")
        }),
        Err(_) => Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("tests")
            .join("vectors")
            .join("delegation-profile"),
    }
}
